// Medical Reading Practice Test 5. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–4.
import {q, mix} from './q.js';
const CA='Crisis Averted (Rivers)', TB='Everything Is Tuberculosis (Green)', FR='Fragmented (Yurkiewicz)', NP='The Next Patient (Grant)', GR='Grit (Duckworth)';
const CDC='CDC', WHO='World Health Organization', AHRQ='Agency for Healthcare Research and Quality', DUCK='Duckworth et al., grit research publications', VAL='Valus Medical Reading lessons';

export default {
 id:'medical-reading-5',
 event:'Medical Reading',
 title:'Practice Test 5',
 subtitle:'Background and ideas behind the five assigned books',
 minutes:60,
 sources:'the five assigned books’ subject areas, with background from the CDC, WHO, AHRQ and published grit research (study the books for chapter details)',
 plan:[{area:CA,weight:20},{area:TB,weight:20},{area:FR,weight:20},{area:NP,weight:20},{area:GR,weight:20}],
 questions:mix([
  q(CA,'In an outbreak investigation, the first case to come to the attention of health officials is called the:','Index case',['Secondary case','Sentinel case','Control case'],'A','The index case is not always the first person infected; that person is the primary case.',CDC),
  q(CA,'An epidemic curve rises sharply and falls within one incubation period. What type of outbreak does this suggest?','A point-source outbreak',['A propagated outbreak','An endemic pattern','A seasonal trend'],'B','A single shared exposure, such as one contaminated meal, produces a tight cluster of cases.',CDC),
  q(CA,'How does incidence differ from prevalence?','Incidence counts new cases; prevalence counts all current cases',['Incidence counts deaths; prevalence counts recoveries','Incidence is used only for chronic diseases','They describe exactly the same measure'],'C','Incidence shows how fast a disease is spreading, while prevalence shows its total burden.',CDC),
  q(CA,'In 8 households, 24 contacts were exposed to a case and 6 became ill. What is the secondary attack rate?','25%',['6%','33%','75%'],'D','Secondary attack rate = new cases among contacts ÷ exposed contacts = 6 ÷ 24 = 25%.',CDC),
  q(CA,'Why do public health labs sequence the genomes of virus samples during an outbreak?','To track variants and how cases are linked',['To replace the need for any case reporting','To make the virus less contagious','To decide which patients may be discharged'],'A','Genomic surveillance can show whether cases share a source and when new variants appear.',CDC),
  q(CA,'Which standardized system gives emergency responders a clear chain of command and shared roles across agencies?','Incident Command System',['Emergency Severity Index','Sentinel Reporting Network','Medical Reserve Registry'],'B','The Incident Command System lets agencies of different sizes and types work together smoothly.',CDC),
  q(CA,'Diseases such as malaria, dengue and Zika, which are spread by mosquitoes or ticks, are called:','Vector-borne diseases',['Foodborne diseases','Airborne diseases','Waterborne diseases'],'C','Controlling vectors, such as draining standing water, is a key prevention step.',WHO),
  q(CA,'How do aerosols differ from droplets in disease spread?','Aerosols are smaller and can stay in the air longer',['Aerosols fall to the ground within seconds','Droplets travel farther than aerosols indoors','Only droplets can carry viruses'],'D','Ventilation and well-fitted respirators help reduce aerosol spread indoors.',CDC),
  q(CA,'Investigators keep a table with one row per case, listing details such as onset date, age and symptoms. What is it called?','A line list',['A case definition','An epidemic curve','A risk matrix'],'A','A line list organizes case details so patterns in person, place and time can be found.',CDC),
  q(CA,'A hospital’s ability to quickly expand staff, beds and supplies during a disaster is called its:','Surge capacity',['Baseline capacity','Patient throughput','Census limit'],'B','Planning for surge capacity before an emergency helps hospitals avoid being overwhelmed.',CDC),
  q(TB,'A healed primary TB lesion in the lung, together with an affected nearby lymph node, is known as the:','Ghon complex',['Pott complex','Koch complex','Miliary complex'],'C','These calcified spots may show on a chest X-ray long after the first infection.',WHO),
  q(TB,'Patients should be told which harmless side effect of rifampin before starting treatment?','Orange-red urine, tears and sweat',['Blue tint to the fingernails','Permanent darkening of the teeth','Green discoloration of the skin'],'D','Rifampin can also stain contact lenses and interacts with many other drugs.',CDC),
  q(TB,'Why is vitamin B6 (pyridoxine) often given with isoniazid?','To prevent nerve damage in the hands and feet',['To speed up how fast the drug kills bacteria','To protect the eyes from color blindness','To stop the urine from turning orange'],'A','Isoniazid can deplete vitamin B6 and cause peripheral neuropathy.',CDC),
  q(TB,'The cheese-like dead tissue found in the center of TB granulomas is called:','Caseous necrosis',['Fatty necrosis','Liquefactive necrosis','Fibrinoid necrosis'],'B','Caseous means cheese-like and is a classic microscopic sign of TB.',WHO),
  q(TB,'Why can a TB culture take several weeks to give a result?','Mycobacterium tuberculosis grows very slowly',['The sample must be frozen first','Cultures are only processed once a month','The bacteria die quickly outside the body'],'C','Molecular tests give faster answers, but culture is still needed to test drug sensitivity.',CDC),
  q(TB,'Without treatment, about what share of people with latent TB infection will develop TB disease during their lifetime?','About 5% to 10%',['About 50%','Nearly 100%','Less than 0.1%'],'D','The risk is much higher in people with weak immune systems, such as those with HIV.',CDC),
  q(TB,'Which first-line TB drug can cause vision problems, so patients need eye checks?','Ethambutol',['Isoniazid','Rifampin','Pyrazinamide'],'A','Ethambutol can cause optic neuritis, which may affect visual sharpness and color vision.',CDC),
  q(TB,'About how many people worldwide fall ill with TB each year, according to the WHO?','About 10 million',['About 100,000','About 1 million','About 100 million'],'B','TB is one of the world’s leading infectious killers, causing over a million deaths a year.',WHO),
  q(TB,'When should a tuberculin skin test be read after it is placed?','Within 48 to 72 hours',['Within 15 minutes','After exactly 7 days','After 2 weeks'],'C','The reader measures the raised, firm area (induration), not just the redness.',CDC),
  q(TB,'Which related bacterium causes TB in cattle and can spread to people through unpasteurized milk?','Mycobacterium bovis',['Mycobacterium leprae','Mycobacterium avium','Mycobacterium marinum'],'D','Pasteurizing milk greatly reduced this form of TB in many countries.',WHO),
  q(FR,'When a patient moves from the hospital to a nursing facility or home, this is called a:','Care transition',['Care escalation','Care rationing','Care restriction'],'A','Transitions are risky moments when information and responsibilities can be lost.',AHRQ),
  q(FR,'A nurse asks a patient to explain the new medicine plan in their own words. What is this method?','Teach-back',['Read-back','Call-out','Check-back'],'B','Teach-back checks understanding and lets the clinician fix any confusion right away.',AHRQ),
  q(FR,'A patient’s ability to find, understand and use health information to make decisions is called:','Health literacy',['Health equity','Health access','Health status'],'C','Low health literacy makes it harder to manage care that is spread across many providers.',AHRQ),
  q(FR,'Under the 21st Century Cures Act, practices that unreasonably stop health data from being shared are called:','Information blocking',['Data mining','Interoperability','Data encryption'],'D','The rule aims to help patients and clinicians access records when and where they are needed.',VAL),
  q(FR,'A patient’s written wishes about end-of-life care cannot be found when they arrive at a new hospital. What document is missing?','An advance directive',['A discharge summary','An incident report','A referral letter'],'A','Advance directives guide care when patients cannot speak for themselves, but only if clinicians can find them.',AHRQ),
  q(FR,'A clinician introduces the next provider to the patient in person and shares information in front of them. What is this?','A warm handoff',['A cold transfer','A blind referral','A silent transition'],'B','Warm handoffs build trust and let the patient correct or add information.',AHRQ),
  q(FR,'Which handoff tool’s name stands for illness severity, patient summary, action list, situation awareness and synthesis by receiver?','I-PASS',['SBAR','SOAP','ISBAR'],'C','Studies of I-PASS found fewer medical errors after resident handoffs.',AHRQ),
  q(FR,'Why are follow-up visits within 7 to 14 days after discharge encouraged?','They catch problems before patients return to the hospital',['They replace the need for any medicine changes','They are required for every patient by law','They allow the hospital to bill twice for one stay'],'D','Early follow-up helps confirm medicines, tests and plans are understood and working.',AHRQ),
  q(FR,'An author supports her argument with statistics on readmissions and costs. Which appeal is she using?','Logos',['Ethos','Pathos','Kairos'],'A','Logos appeals to logic and evidence; ethos to credibility; pathos to emotion.',VAL),
  q(FR,'A book describes problems in health care and urges readers and policymakers to support change. What is its main purpose?','To persuade',['To entertain only','To instruct in a skill','To describe a process neutrally'],'B','Recognizing the author’s purpose helps readers judge how evidence is chosen and presented.',VAL),
  q(NP,'For a stroke patient who may receive a clot-busting drug, which measure tracks the time from arrival to treatment?','Door-to-needle time',['Door-to-balloon time','Length of stay','Time to discharge'],'C','For stroke, faster treatment saves more brain tissue, so hospitals set strict targets.',CDC),
  q(NP,'Which bedside tool uses breathing rate, mental status and blood pressure to flag patients at risk of poor outcomes from sepsis?','qSOFA',['APGAR','NIHSS','Glasgow Coma Scale'],'D','A positive qSOFA prompts closer checks for organ damage from infection.',CDC),
  q(NP,'A patient handed off as “just anxious” is seen through that lens by the next doctor. Which bias is this?','Framing effect',['Search satisficing','Hindsight bias','Overconfidence bias'],'A','How information is presented can shape the next clinician’s thinking before they see the patient.',AHRQ),
  q(NP,'A clinician ignores how common a disease is in the population when judging a positive test. Which error is this?','Base-rate neglect',['Anchoring','Visceral bias','Premature closure'],'B','A positive test for a very rare disease is often a false positive, even with a good test.',AHRQ),
  q(NP,'A young, fit runner with chest pain is sent home because he “does not look like” a heart attack patient. Which bias is this?','Representativeness restraint',['Availability bias','Posterior probability error','Sunk cost bias'],'C','Atypical patients can still have serious disease, so classic patterns should not rule it out.',AHRQ),
  q(NP,'Which model describes fast, intuitive thinking and slower, analytical thinking in diagnosis?','Dual process theory',['Swiss cheese model','Stages of change model','Health belief model'],'D','Many diagnostic errors occur when fast thinking is not checked by slower reasoning.',AHRQ),
  q(NP,'A test is negative. Which measure tells the chance the patient truly does not have the disease?','Negative predictive value',['Sensitivity','Positive predictive value','Prevalence'],'A','Predictive values depend on how common the disease is in the group being tested.',AHRQ),
  q(NP,'A patient chooses to leave the ED before the doctor recommends discharge. What is this called?','Leaving against medical advice',['Leaving without being seen','A transfer to another facility','A planned discharge'],'B','Clinicians should explain the risks and invite the patient to return at any time.',AHRQ),
  q(NP,'In trauma care, the primary survey checks airway, breathing, circulation, disability and what else?','Exposure',['Examination','Evaluation','Elevation'],'C','The ABCDE approach finds and treats the most immediate threats to life first.',CDC),
  q(NP,'Why is the first hour after a serious injury often called the “golden hour”?','Fast treatment then greatly improves survival',['Hospital staff change shifts at that time','It is when pain first begins','Insurance only covers that hour'],'D','Rapid transport to a trauma center and quick treatment can prevent many deaths.',CDC),
  q(GR,'On the Grit Scale, “New ideas and projects sometimes distract me from previous ones” is reverse-scored. Which part of grit does it measure?','Consistency of interest',['Perseverance of effort','Self-control','Growth mindset'],'A','Agreeing with this item lowers the grit score because it shows shifting interests.',DUCK),
  q(GR,'Doing an activity because it is enjoyable or meaningful in itself is called:','Intrinsic motivation',['Extrinsic motivation','Learned helplessness','Social comparison'],'B','Duckworth argues that lasting passion often grows from activities people enjoy.',DUCK),
  q(GR,'Which psychologist is best known for research on growth and fixed mindsets?','Carol Dweck',['Martin Seligman','Anders Ericsson','Walter Mischel'],'C','Duckworth cites Dweck’s work when explaining how beliefs about ability affect persistence.',DUCK),
  q(GR,'A study of only top performers finds grit barely predicts success within that group. Which issue may explain this?','Restriction of range',['Test-retest reliability','Random assignment','Informed consent'],'D','When everyone in a sample scores similarly, it is harder to see a relationship.',DUCK),
  q(GR,'Researchers measure students’ grit and then follow their school outcomes for several years. What design is this?','A longitudinal study',['A cross-sectional study','A case report','A controlled experiment'],'A','Following people over time shows whether grit comes before later outcomes.',DUCK),
  q(GR,'Whose research on expert performers introduced the idea of deliberate practice that Duckworth builds on?','Anders Ericsson',['Carol Dweck','Angela Lee','Lewis Terman'],'B','Ericsson studied how experts improve through focused, effortful practice with feedback.',DUCK),
  q(GR,'Researchers ask whether a grit questionnaire truly measures grit and not something else. Which property is this?','Construct validity',['Test-retest reliability','Internal consistency','Inter-rater agreement'],'C','A measure with good construct validity captures the idea it claims to measure.',DUCK),
  q(GR,'Students at a demanding school rate themselves lower on grit because they compare themselves with very hard-working peers. What is this problem?','Reference bias',['Recall bias','Selection bias','Observer bias'],'D','Self-report scores depend on each person’s own standard, which can differ between schools.',DUCK),
  q(GR,'Which point does Duckworth make about quitting?','It can be wise to quit low-level goals that do not serve a top goal',['Gritty people should never quit anything they start','Quitting always shows a lack of character','Goals should be changed every few weeks'],'A','Grit means staying loyal to a top goal while being flexible about how to reach it.',DUCK),
  q(GR,'In Duckworth’s data, how did grit scores tend to change with age?','Older adults tended to score higher',['Teens tended to score highest','Scores dropped steadily with age','Age made no difference at all'],'B','This pattern suggests grit may grow with life experience, though other explanations are possible.',DUCK)
 ],9540)
};
